1675	// Attaches compensation results to a failed run. Successful outputs and the
1676	// original terminal status stay untouched; compensation records live on
1677	// their own fields, never in the regular node trace.
1678	async function withCompensation(result, state, operations) {
1679	  const outcome = await compensateRun(state, operations);
1680	  result.compensationStatus = outcome.attempts.length === 0 ? 'not_needed' : outcome.status;
1681	  result.compensationAttempts = outcome.attempts;
