1	import test from 'node:test';
2	import assert from 'node:assert/strict';
3	import { executeWorkflow, executeWorkflowAsync } from '../src/engine.js';
4	
5	// Regression coverage for form rollback when the caller's input is a legal
6	// plain-object graph with shared and circular references: two fields point at
7	// the same ordinary object, and a field points back at the root. These are
8	// ordinary references, not shared memory — structuredClone preserves the
9	// topology, so the run input, the per-form snapshot and the rollback restore
10	// must all keep it intact.
11	//
12	// Shared shape for both entry points (neither workflow names a business
13	// operation, so the asynchronous run needs no implementations):
14	//
15	//   start -> prep (message action) -> form-one (succeeds, applies defaults)
16	//         -> form-two (writes into the shared object and creates fresh parent
17	//                      chains, then fails validation)
18	//         -> after (end, never reached)
19	//
20	// The failing form exercises every rollback boundary under references:
21	// - left.temp lands in the shared object the caller supplied — visible through
22	//   input.right and through the cycle input.self.left as well;
23	// - fresh.parent.deep creates a wholly new parent chain;
24	// - missing.required is a missing required value;
25	// - count is present but wrong-typed despite carrying a default.
26	function referenceRollbackWorkflow() {
27	  return {
28	    id: 'form-rollback-references',
29	    entry: 'start',
30	    nodes: [
31	      { id: 'start', type: 'trigger', next: 'prep' },
32	      { id: 'prep', type: 'action', message: 'prepared', next: 'form-one' },
33	      { id: 'form-one', type: 'form', next: 'form-two', schema: { fields: [
34	        { path: 'one.top', type: 'string', default: 'A' },
35	        { path: 'left.fromOne', type: 'string', default: 'L1' },
36	      ] } },
37	      { id: 'form-two', type: 'form', next: 'after', schema: { fields: [
38	        { path: 'left.temp', type: 'string', default: 'T' },
39	        { path: 'fresh.parent.deep', type: 'string', default: 'deep' },
40	        { path: 'missing.required', type: 'string', required: true },
41	        { path: 'count', type: 'integer', default: 7 },
42	      ] } },
43	      { id: 'after', type: 'end', result: 'done' },
44	    ],
45	  };
46	}
47	
48	// left and right are the same object; self points back at the root, so the
49	// shared object is also reachable as self.left / self.right.
50	const callerInput = () => {
51	  const shared = { original: 'kept' };
52	  const root = {
53	    raw: 'value',
54	    left: shared,
55	    right: shared,
56	    count: 'many',
57	  };
58	  root.self = root;
59	  return root;
60	};
61	
62	// The run input once form-two fails: caller data verbatim, form-one's
63	// defaults retained (including the one written into the shared object),
64	// everything form-two wrote undone — with the original reference topology.
65	const expectedRolledBackInput = () => {
66	  const shared = { original: 'kept', fromOne: 'L1' };
67	  const root = {
68	    raw: 'value',
69	    left: shared,
70	    right: shared,
71	    count: 'many',
72	    one: { top: 'A' },
73	  };
74	  root.self = root;
75	  return root;
76	};
77	
78	const expectedErrors = () => ([
79	  { nodeId: 'form-two', path: 'missing.required', code: 'required' },
80	  { nodeId: 'form-two', path: 'count', code: 'type' },
81	]);
82	
83	const expectedTraceIds = ['start', 'prep', 'form-one', 'form-two'];
84	
85	function assertRolledBackReferences(input) {
86	  assert.deepEqual(input, expectedRolledBackInput());
87	
88	  // The restored input is not just field-equal: the reference relationships
89	  // survive the rollback. Fields that pointed at the same object still do,
90	  // and the cycle still returns to the restored root — no stale reference to
91	  // the pre-rollback (temporarily mutated) graph remains.
92	  assert.equal(input.self, input);
93	  assert.equal(input.left, input.right);
94	  assert.equal(input.self.left, input.right);
95	  assert.equal(input.self.self, input);
96	
97	  // The failed form's leaf is gone from the shared object no matter which
98	  // reference reaches it: the direct one, the sibling alias, or the cycle.
99	  for (const view of [input.left, input.right, input.self.left]) {
100	    assert.equal(Object.hasOwn(view, 'temp'), false);
101	  }
102	  // The parent chain created solely for the failed form's default is gone
103	  // entirely, again also when reached through the cycle.
104	  assert.equal(Object.hasOwn(input, 'fresh'), false);
105	  assert.equal(Object.hasOwn(input, 'missing'), false);
106	  assert.equal(Object.hasOwn(input.self, 'fresh'), false);
107	
108	  // The pre-existing shared parent keeps its original child and the earlier
109	  // successful form's default; only the failed form's write was undone.
110	  assert.deepEqual(input.left, { original: 'kept', fromOne: 'L1' });
111	  // The parent the successful form created survives with its child.
112	  assert.deepEqual(input.one, { top: 'A' });
113	
114	  // The present-but-wrong-typed value is kept as-is: it was not treated as
115	  // missing, so the integer default never replaced it.
116	  assert.equal(input.count, 'many');
117	}
118	
119	function assertCallerUntouched(caller, callerSnapshot) {
120	  // The caller's original object is never mutated — data and reference
121	  // relationships alike — and the successful form's defaults never leak into
122	  // it; they exist only in the run input.
123	  assert.deepEqual(caller, callerSnapshot);
124	  assert.equal(caller.self, caller);
125	  assert.equal(caller.left, caller.right);
126	  assert.deepEqual(caller.left, { original: 'kept' });
127	  assert.equal(Object.hasOwn(caller, 'one'), false);
128	  assert.equal(Object.hasOwn(caller, 'fresh'), false);
129	}
130	
131	function assertIndependentCopy(input, caller) {
132	  // The returned run input is an independent copy of the caller's input at
133	  // every level of the shared structure.
134	  assert.notEqual(input, caller);
135	  assert.notEqual(input.left, caller.left);
136	  assert.notEqual(input.self, caller);
137	}
138	
139	test('async run: a failed form rolls back its own writes across shared and circular references', async () => {
140	  const workflow = referenceRollbackWorkflow();
141	  const caller = callerInput();
142	  const callerSnapshot = structuredClone(caller);
143	
144	  const result = await executeWorkflowAsync(workflow, caller);
145	
146	  assert.equal(result.status, 'invalid_input');
147	  // Errors keep their declaration order, node id, field path and usual code.
148	  assert.deepEqual(result.errors, expectedErrors());
149	
150	  // The failed form is traced; its successor never runs; the earlier
151	  // action's saved output is not lost.
152	  assert.deepEqual(result.trace.map(node => node.nodeId), expectedTraceIds);
153	  assert.equal(result.trace.some(node => node.nodeId === 'after'), false);
154	  assert.deepEqual(result.context.output, { prep: 'prepared' });
155	  assert.deepEqual(result.actionAttempts, []);
156	  assert.equal(result.compensationStatus, 'not_needed');
157	
158	  assertRolledBackReferences(result.context.input);
159	  assertCallerUntouched(caller, callerSnapshot);
160	  assertIndependentCopy(result.context.input, caller);
161	});
162	
163	test('sync run: the same reference-aware rollback rules hold through executeWorkflow', () => {
164	  const workflow = referenceRollbackWorkflow();
165	  const caller = callerInput();
166	  const callerSnapshot = structuredClone(caller);
167	
168	  const result = executeWorkflow(workflow, caller);
169	
170	  assert.equal(result.status, 'invalid_input');
171	  assert.deepEqual(result.errors, expectedErrors());
172	  assert.deepEqual(result.trace.map(node => node.nodeId), expectedTraceIds);
173	  assert.equal(result.trace.some(node => node.nodeId === 'after'), false);
174	  assert.deepEqual(result.context.output, { prep: 'prepared' });
175	
176	  assertRolledBackReferences(result.context.input);
177	  assertCallerUntouched(caller, callerSnapshot);
178	  assertIndependentCopy(result.context.input, caller);
179	});
180	
181	// Control under the same reference structure: when validation succeeds, the
182	// defaults the form wrote — including the one landing in the shared object —
183	// stay in place and a successor reads them through the other alias.
184	function referenceSuccessWorkflow() {
185	  return {
186	    id: 'form-references-success',
187	    entry: 'start',
188	    nodes: [
189	      { id: 'start', type: 'trigger', next: 'form-one' },
190	      { id: 'form-one', type: 'form', next: 'check', schema: { fields: [
191	        { path: 'left.fromOne', type: 'string', default: 'L1' },
192	        { path: 'one.top', type: 'string', default: 'A' },
193	      ] } },
194	      // Reads the default through `right`, the alias the form never wrote to.
195	      { id: 'check', type: 'condition', then: 'seen', else: 'missed',
196	        condition: { field: 'right.fromOne', operator: 'eq', value: 'L1' } },
197	      { id: 'seen', type: 'end', result: 'default-visible' },
198	      { id: 'missed', type: 'end', result: 'default-missing' },
199	    ],
200	  };
201	}
202	
203	function assertSuccessReferences(input) {
204	  // The successful defaults are present on every view of the shared object,
205	  // and the caller's reference topology is intact in the run input.
206	  assert.equal(input.self, input);
207	  assert.equal(input.left, input.right);
208	  assert.equal(input.left.fromOne, 'L1');
