        { path: 'request.createdAt.after', type: 'string', default: 'late' },
        { path: 'later.only', type: 'string', default: 'late' },
      ] } },
      { id: 'boom', type: 'action', operation: 'boom', next: 'done' },
      { id: 'done', type: 'end', result: 'ok' },
    ],
  };
