  const result = await executeWorkflowAsync(workflow, caller, {
    op: (input) => {
      assertDateWithDefaults(input);
      return { id: 'tx-1' };
    },
    undo: (input, output, returned, nodeId, attempt) => {
      compensationSeen.push({ input, output, returned, nodeId, attempt });
