  assert.equal(result.nodeId, 'boom');
  assert.equal(result.compensationStatus, 'completed');
  assert.deepEqual(result.compensationAttempts.map(r => [r.nodeId, r.operation, r.attempt, r.ok, r.result]), [
    ['act', 'undo', 1, false, null],
    ['act', 'undo', 2, false, null],
    ['act', 'undo', 3, true, 'released'],
  ]);

  // Every attempt received the same pristine success-moment input — the
  // earlier attempts' rewrites were discarded.
  assert.equal(compensationSeen.length, 3);
  for (const seen of compensationSeen) {
    assert.equal(seen.input.request.createdAt.getTime(), WHEN);
    assert.equal(seen.input.request.createdAt.channel, 'web');
    assert.equal(seen.input.request.createdAt.meta.source, 'form');
    assert.equal(seen.input.plain.pair.x, 'X');
    assert.equal(Object.hasOwn(seen.input.request.createdAt, 'after'), false);
    assert.equal(Object.hasOwn(seen.input.request.createdAt, 'addedByUndo'), false);
    assert.equal(Object.hasOwn(seen.input, 'later'), false);
    assert.equal(seen.input.request.createdAt, seen.input.note.at);
    assert.equal(seen.nodeId, 'act');
