test('async: a default on a Date reached through an array index is preserved as well', async () => {
  const workflow = {
    id: 'date-behind-array',
    entry: 'start',
    nodes: [
      { id: 'start', type: 'trigger', next: 'form-one' },
      { id: 'form-one', type: 'form', next: 'act', schema: { fields: [
        { path: 'items.0.at.channel', type: 'string', default: 'web' },
      ] } },
      { id: 'act', type: 'action', operation: 'op', next: 'done' },
      { id: 'done', type: 'end', result: 'ok' },
    ],
  };
  const createdAt = new Date(WHEN);
  const caller = { items: [{ at: createdAt }, { at: createdAt }] };
  const result = await executeWorkflowAsync(workflow, caller, {
    op: (input) => {
      for (const item of input.items) {
        assert.ok(item.at instanceof Date);
        assert.equal(item.at.getTime(), WHEN);
        assert.equal(item.at.channel, 'web');
      }
      // The two array entries aliased one Date; inside this copy they still
      // share the single copied Date carrying the default.
      assert.equal(input.items[0].at, input.items[1].at);
      return 'done';
    },
  });
  assert.equal(result.status, 'completed');
  assert.equal(result.context.input.items[0].at.channel, 'web');
  assert.ok(result.context.input.items[0].at instanceof Date);
  assert.equal(caller.items[0].at.channel, undefined);
});

