1	import test from 'node:test';
2	import assert from 'node:assert/strict';
3	import { executeWorkflow, executeWorkflowAsync } from '../src/engine.js';
4	
5	// Regression coverage for defaults a successful form attaches to a host object
6	// (a Date) during a run. Forms apply defaults directly on the live run input,
7	// so context.input and later conditions always saw them; but business-action
8	// argument copies and compensation snapshots used to be plain structured
9	// clones, and structuredClone reproduces a Date from its time value alone,
10	// silently dropping every attached own property — so the action and its
11	// compensation lost exactly the run-time form defaults. These tests pin the
12	// fix: the same defaults are visible in every copy, the Date keeps its type
13	// and time, aliases stay aliases within one copy, and every copy is
14	// independent of the run input, the caller's input and every other copy.
15	
16	const WHEN = Date.parse('2024-01-02T03:04:05.000Z');
17	
18	// start -> form-one (adds defaults, including onto the input Date)
19	//       -> act (business + compensation in async runs; a message in sync)
20	//       -> check (condition reading a default attached to the Date)
21	//       -> seen / missed (two ends)
22	function dateDefaultWorkflow(actNode) {
23	  return {
24	    id: 'date-form-defaults',
25	    entry: 'start',
26	    nodes: [
27	      { id: 'start', type: 'trigger', next: 'form-one' },
28	      { id: 'form-one', type: 'form', next: 'act', schema: { fields: [
29	        // A default landing directly on the caller's Date.
30	        { path: 'request.createdAt.channel', type: 'string', default: 'web' },
31	        // A multi-level path where every parent above the leaf is created on
32	        // the Date during the run.
33	        { path: 'request.createdAt.meta.source', type: 'string', default: 'form' },
34	        { path: 'request.createdAt.meta.kind', type: 'string', default: 'kind-default' },
35	        // Plain-object defaults keep their existing behavior.
36	        { path: 'plain.pair.x', type: 'string', default: 'X' },
37	      ] } },
38	      actNode,
39	      {
40	        id: 'check', type: 'condition', then: 'seen', else: 'missed',
41	        condition: { all: [
42	          { field: 'request.createdAt.channel', operator: 'eq', value: 'web' },
43	          { field: 'request.createdAt.meta.source', operator: 'eq', value: 'form' },
44	        ] },
45	      },
46	      { id: 'seen', type: 'end', result: 'default-visible' },
47	      { id: 'missed', type: 'end', result: 'default-missing' },
48	    ],
49	  };
50	}
51	
52	// Two input fields point at the same Date; both must keep aliasing the one
53	// copied Date inside each independent copy.
54	function callerInput() {
55	  const createdAt = new Date(WHEN);
56	  return { request: { createdAt }, note: { at: createdAt } };
57	}
58	
59	function assertDateWithDefaults(input) {
60	  assert.ok(input.request.createdAt instanceof Date, 'the value stays a Date');
61	  assert.equal(input.request.createdAt.getTime(), WHEN, 'the Date keeps its time value');
62	  assert.equal(input.request.createdAt.channel, 'web');
63	  // The whole newly-created multi-level path is readable.
64	  assert.deepEqual(input.request.createdAt.meta, { source: 'form', kind: 'kind-default' });
65	  assert.equal(input.plain.pair.x, 'X');
66	}
67	
68	test('async: a business action reads defaults a form attached to a Date, with type and time preserved', async () => {
69	  const workflow = dateDefaultWorkflow({
70	    id: 'act', type: 'action', operation: 'op',
71	    compensation: { operation: 'undo' }, next: 'check',
72	  });
73	  const caller = callerInput();
74	  const seen = [];
75	  const result = await executeWorkflowAsync(workflow, caller, {
76	    op: (input, output, nodeId, attempt) => {
77	      seen.push({ alias: input.request.createdAt === input.note.at, output: structuredClone(output), nodeId, attempt });
78	      assertDateWithDefaults(input);
79	      // Two input fields aliasing one Date still alias the one copied Date
80	      // inside this invocation's copy.
81	      assert.equal(input.request.createdAt, input.note.at);
82	      assert.equal(input.note.at.meta.source, 'form');
83	      // The copy is independent of the caller's Date.
84	      assert.notEqual(input.request.createdAt, caller.request.createdAt);
85	      // Mutating this attempt's copy: the time, the attached defaults, the
86	      // created parent and a brand-new own property all stay within the copy.
87	      input.request.createdAt.setTime(0);
88	      input.request.createdAt.channel = 'hacked';
89	      delete input.request.createdAt.meta.kind;
90	      input.request.createdAt.addedByAction = true;
91	      input.plain.pair.x = 'Z';
92	      return { ok: true };
93	    },
94	    undo: () => 'undone',
95	  });
96	
97	  assert.equal(result.status, 'completed');
98	  assert.equal(result.result, 'default-visible', 'the condition read the defaults straight off context.input');
99	  assert.deepEqual(result.trace.map(n => n.nodeId), ['start', 'form-one', 'act', 'check', 'seen']);
100	  assert.equal(seen.length, 1);
101	  assert.equal(seen[0].alias, true);
102	  assert.equal(seen[0].nodeId, 'act');
103	  assert.equal(seen[0].attempt, 1);
104	
105	  // The run result keeps the same defaults on the live Date.
106	  assertDateWithDefaults(result.context.input);
107	  assert.equal(result.context.input.note.at, result.context.input.request.createdAt);
108	  // Nothing the action did to its own copy reached the run input.
109	  assert.equal(result.context.input.request.createdAt.getTime(), WHEN);
110	  assert.equal(Object.hasOwn(result.context.input.request.createdAt, 'addedByAction'), false);
111	
112	  // The caller's object and Date were never mutated, nor given the defaults.
113	  assert.equal(caller.request.createdAt.getTime(), WHEN);
114	  assert.equal(caller.request.createdAt.channel, undefined);
115	  assert.equal(caller.request.createdAt.meta, undefined);
116	  assert.equal(Object.hasOwn(caller, 'plain'), false);
117	  assert.equal(caller.note.at, caller.request.createdAt);
118	});
119	
120	test('async: retries each receive the complete independent copy as of their own moment', async () => {
121	  const workflow = dateDefaultWorkflow({
122	    id: 'act', type: 'action', operation: 'op',
123	    retry: { attempts: 2, initialDelayMs: 0, backoffFactor: 1, maxDelayMs: 0 },
124	    next: 'check',
125	  });
126	  const result = await executeWorkflowAsync(workflow, callerInput(), {
127	    op: (input, output, nodeId, attempt) => {
128	      assertDateWithDefaults(input);
129	      assert.equal(input.request.createdAt, input.note.at);
130	      if (attempt === 1) {
131	        // Ruin every part of this attempt's copy, then fail.
132	        input.request.createdAt.setTime(0);
133	        input.request.createdAt.channel = 'hacked';
134	        input.request.createdAt.meta.source = 'hacked';
135	        input.request.createdAt.newParent = { deep: 'hacked' };
136	        input.plain.pair.x = 'Z';
137	        throw new Error('first attempt fails');
138	      }
139	      return { ok: true };
140	    },
141	  });
142	
143	  assert.equal(result.status, 'completed');
144	  // Attempt 2 still saw the pristine time and defaults — the failed
145	  // attempt's copy was discarded whole.
146	  assert.equal(result.context.input.request.createdAt.getTime(), WHEN);
147	  assert.equal(result.context.input.request.createdAt.channel, 'web');
148	  assert.equal(result.context.input.request.createdAt.meta.source, 'form');
149	  assert.equal(Object.hasOwn(result.context.input.request.createdAt, 'newParent'), false);
150	  assert.equal(result.context.input.plain.pair.x, 'X');
151	});
152	
153	test('async: compensation keeps only the defaults effective before the action succeeded', async () => {
